import assert from 'node:assert/strict';import {performance} from 'node:perf_hooks';import {writeFileSync} from 'node:fs';import Worker from '../dist/server/index.js';import {fixture} from './friend-server.mjs';
const realNow=Date.now;let now=realNow();Date.now=()=>now;const team={items:[{char:'一',level:10,equippedReadings:['イチ']},{char:'山',level:10,equippedReadings:['サン']},{char:'小',level:10,equippedReadings:['ショウ']}],ruleSet:'balanced'},all=[];
for(const users of [10,50,100,200]){const f=fixture({measure:true}),clients=[],latencies={},unexpected=[];let requestCount=0;const percentile=(xs,p)=>xs.slice().sort((a,b)=>a-b)[Math.min(xs.length-1,Math.floor(xs.length*p))];async function call(i,path,method='GET',body,accepted=[200]){const c=clients[i],t=performance.now();const r=await Worker.fetch(new Request('https://capacity.test'+path,{method,headers:{...(c?{'X-Kanji-Guest':c.token,'X-Kanji-Guest-Mode':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})}),f.env);const responseText=await r.text(),value=JSON.parse(responseText);const route=method+' '+path.split('?')[0].replace(/\/rooms\/[A-Z2-9]+/,'/rooms/:code');(latencies[route]??=[]).push(performance.now()-t);requestCount++;if(!accepted.includes(r.status))unexpected.push({route,status:r.status,error:value.error});return {status:r.status,value,bytes:Buffer.byteLength(responseText)};}const value=r=>r.value;const stage={users,phases:{}};async function wave(name,fn){f.resetMetrics();const start=performance.now(),data=await fn();stage.phases[name]={ms:+(performance.now()-start).toFixed(2),reads:f.metrics.reads,writes:f.metrics.writeStatements,rowsWritten:f.metrics.rowsWritten};return data;}
try{
 for(let i=0;i<users;i++){clients.push(null);clients[i]=value(await call(i,'/api/guest','POST',{}));}
 await Promise.all(clients.map((c,i)=>call(i,'/api/profile','PUT',{name:'負荷テスト'+i,char:'一',frame:'plain',color:'gold',glow:'none'})));
 const states=clients.map((c,i)=>({inventory:Array.from({length:1000},(_,n)=>({instanceId:'i'+n,char:'一',level:10})),deck:[],coins:100+i,rating:1000,ownerMarker:i}));stage.snapshotBytes=Buffer.byteLength(JSON.stringify({state:states[0],revision:0}));
 await wave('backupWrites',()=>Promise.all(states.map((state,i)=>call(i,'/api/guest/state','PUT',{state,revision:0}))));
 await wave('backupReads',async()=>{const results=await Promise.all(clients.map((c,i)=>call(i,'/api/guest/state')));results.forEach((r,i)=>{assert.equal(r.value.state.ownerMarker,i);assert.equal(r.value.state.coins,100+i);assert.equal(r.value.state.inventory.length,1000);});});
 const collision=await wave('samePlayerWriteRace',()=>Promise.all([call(0,'/api/guest/state','PUT',{state:{...states[0],coins:501},revision:1},[200,409]),call(0,'/api/guest/state','PUT',{state:{...states[0],coins:502},revision:1},[200,409])]));assert.deepEqual(collision.map(r=>r.status).sort(),[200,409]);const saved=value(await call(0,'/api/guest/state'));assert([501,502].includes(saved.state.coins));assert.equal(saved.revision,2);
 await Promise.all(clients.map((c,i)=>call(i,'/api/challenges/score','POST',{mode:'endless',wins:1+i%20,kills:3*(1+i%20),items:team.items})));
 await wave('rankingCold',async()=>{const results=await Promise.all(clients.map((c,i)=>call(i,'/api/leaderboard?rule=endless')));assert(results.every(r=>r.status===200&&r.value.entries.length===10));});
 await wave('rankingCached',()=>Promise.all(clients.map((c,i)=>call(i,'/api/leaderboard?rule=endless'))));
 await wave('matching',async()=>{await Promise.all(clients.map((c,i)=>call(i,'/api/online/queue','POST',team)));});
 const queued=await Promise.all(clients.map((c,i)=>call(i,'/api/online/queue'))),rooms=new Map();queued.forEach((r,i)=>{if(r.value.room){const room=r.value.room;const p=rooms.get(room.code)||[];p.push(i);rooms.set(room.code,p);}});assert.equal(rooms.size,users/2);assert([...rooms.values()].every(x=>x.length===2));stage.rooms=rooms.size;const active=[];
 await wave('ready',async()=>{await Promise.all([...rooms].map(async([code,members])=>{let room=value(await call(members[0],'/api/friends/rooms/'+code));for(const i of members)room=value(await call(i,'/api/friends/rooms/'+code+'/ready','POST',{round:room.round,revision:room.revision,lineupRevision:room.lineupRevision,ready:true}));assert.equal(room.status,'playing');active.push({code,members,room});}));});
 await wave('heartbeat6Seconds',async()=>{let bytes=0;for(let tick=0;tick<6;tick++){now+=1000;const replies=await Promise.all(active.flatMap(({code,members,room})=>members.map(i=>call(i,'/api/friends/rooms/'+code+'?since='+room.revision))));assert(replies.every(r=>r.value.unchanged));bytes+=replies.reduce((a,r)=>a+r.bytes,0);}stage.heartbeatBytes=bytes;});
 await wave('shots',async()=>{await Promise.all(active.map(async({code,members,room})=>{const sides=await Promise.all(members.map(i=>call(i,'/api/friends/rooms/'+code)));const actor=members[sides.findIndex(r=>r.value.side===room.state.turn)],body={id:Buffer.from(code).toString('hex').padEnd(32,'0').slice(0,32),revision:room.revision,key:room.state.turn*3,dx:0,dy:room.state.turn?1:-1,power:.001,spin:0};const result=await call(actor,'/api/friends/rooms/'+code+'/shot','POST',body);assert.equal(result.status,200,JSON.stringify(result.value));assert.equal(result.value.revision,room.revision+1);const duplicate=await call(actor,'/api/friends/rooms/'+code+'/shot','POST',body);assert.equal(duplicate.value.revision,result.value.revision);}));});
 now+=30001;const ended=await wave('finish',()=>Promise.all(active.map(async({code,members})=>{f.sqlite.prepare('UPDATE friend_rooms SET seen_host=?,seen_guest=? WHERE code=?').run(now-1000,now-1000,code);return call(members[0],'/api/friends/rooms/'+code);})));assert(ended.every(r=>r.value.status==='finished'));
 await wave('finishRepeated',()=>Promise.all(active.flatMap(({code,members})=>Array.from({length:4},(_,n)=>call(members[n%2],'/api/friends/rooms/'+code)))));
 assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM online_results').get().n,users/2);assert.equal(f.sqlite.prepare('SELECT SUM(wins+losses+draws) n FROM online_stats').get().n,users);
 assert.equal(unexpected.length,0,JSON.stringify(unexpected));stage.requests=requestCount;stage.unexpected=unexpected;stage.latency=Object.fromEntries(Object.entries(latencies).map(([k,v])=>[k,{calls:v.length,p50:+percentile(v,.5).toFixed(2),p95:+percentile(v,.95).toFixed(2),max:+Math.max(...v).toFixed(2)}]));all.push(stage);console.log(JSON.stringify({users,rooms:stage.rooms,requests:requestCount,errors:unexpected.length,phases:stage.phases}));
}finally{f.sqlite.close();}}
Date.now=realNow;writeFileSync(new URL('../docs/capacity-20261018.json',import.meta.url),JSON.stringify({environment:'Node Worker.fetch + isolated in-memory SQLite; no real HTTP network/D1 quotas/CDN; 1,000 minimal inventory entries per player',stages:all},null,2));
